commands.command:
/bin/zsh -lc python - <<'PY'
import importlib.util
import subprocess

from humanize import intword
from humanize.number import human_powers, powers

for i, power in enumerate(powers[1:], start=1):
    unit = human_powers[i][0]
    for sign in (1, -1):
        prefix = '-' if sign < 0 else ''
        for convert in (int, str):
            for fmt in ('%.0f', '%.1f', '%.3f', '%.4g'):
                assert intword(convert(sign * (power - 1)), fmt) == f'{prefix}{fmt % 1} {unit}'
for exponent in range(6, 34, 3):
    value = 9999 * 10 ** (exponent - 4)
    assert intword(value).startswith('999.9 ')
assert intword(10**36) == '1000.0 decillion'
assert intword(2 * 10**100) == '2.0 googol'
print('Boundary checks passed: signs, integer/string inputs, custom precision, carry thresholds, and decillion/googol gap.')
for module, args in [('ruff', ['check', '--no-fix', 'src/humanize/number.py']), ('black', ['--check', 'src/humanize/number.py'])]:
    if importlib.util.find_spec(module) is None:
        print(f'{module}: unavailable; check not run')
    else:
        subprocess.run(['python', '-m', module, *args], check=True)
PY

